// The `self-fs` route for #59: a module reached through this package's OWN `exports` map, by its
// package NAME rather than by a relative path (Node's self-reference). Node's `exports` targets
// must start with "./", so an exports entry cannot name a builtin directly — the laundering shape
// is a self-referenced module that re-exports one, and it re-exports it through the subpath-imports
// map so the specifier string never says `fs` anywhere on the path.
export * from "#bare-fs";
